(6718845, 1005362, 142473, '<td valign="top">Just... creepy... but a good clown portrait.</td>', 'Just... creepy... but a good clown portrait.', '2012-03-21 12:28:40.000000', NULL, 1),
(6718847, 1005383, 142473, '<td valign="top">There should be an ADT logo on this image.  Seriously though, great image.  Good expression on the model''s face, good grit on the windows.  Only improvement would be GLOVES!  Your intruder is leaving a lot of fingerprints!</td>', 'There should be an ADT logo on this image.  Seriously though, great image.  Good expression on the model''s face, good grit on the windows.  Only improvement would be GLOVES!  Your intruder is leaving a lot of fingerprints!', '2012-03-21 12:30:54.000000', NULL, 1),
