(6718851, 1005467, 142473, '<td valign="top">I really want to like this image.  Smaller earrings would be one slight improvement.  I see some artifacts under the nose too, which is a bit distracting.  Overall a really nice glamor shot. 7</td>', 'I really want to like this image.  Smaller earrings would be one slight improvement.  I see some artifacts under the nose too, which is a bit distracting.  Overall a really nice glamor shot. 7', '2012-03-21 12:34:07.000000', NULL, 1),
(6718862, 1005482, 46202, '<td valign="top">6 for it being a super creative idea!  If this were a little brighter with more dimensional light and a better composition, it would be fantastic!</td>', '6 for it being a super creative idea!  If this were a little brighter with more dimensional light and a better composition, it would be fantastic!', '2012-03-21 12:47:19.000000', NULL, 1),
