(6720132, 1005484, 46202, '<td valign="top">Lovely high key - interesting composition.  Bumped this up to 9...I only wish there was a touch more DoF to sharpen her iris.  :o)</td>', 'Lovely high key - interesting composition.  Bumped this up to 9...I only wish there was a touch more DoF to sharpen her iris.  :o)', '2012-03-22 14:31:47.000000', NULL, 1),
(6720134, 1005397, 46202, '<td valign="top">I''m not entirely sure what I''m looking at (aside from the glasses at the top) but I really like this.  LoL  Makes me think of Rorschach images - 8</td>', 'I''m not entirely sure what I''m looking at (aside from the glasses at the top) but I really like this.  LoL  Makes me think of Rorschach images - 8', '2012-03-22 14:32:59.000000', NULL, 1),
