INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6720447, 1005279, 23267, '<td valign="top">As a rule, I generally don''t love cat pictures or gratuitous B&amp;W... this is an exception on both fronts.</td>', 'As a rule, I generally don''t love cat pictures or gratuitous B&W... this is an exception on both fronts.', '2012-03-22 19:56:19.000000', NULL, 1),
(6720516, 1004813, 10785, '<td valign="top">I really like the colors and the sparkly glasses are cool. The way you used the light in the shades was a neat trick. The processing is good and the only real negative comment is that the square crop really accentuates the length of the womans face. I kind of reframed the shot in my browser cutting off the edge for a more rectangular crop which helped balance the image a bit more.</td>', 'I really like the colors and the sparkly glasses are cool. The way you used the light in the shades was a neat trick. The processing is good and the only real negative comment is that the square crop really accentuates the length of the womans face. I kind of reframed the shot in my browser cutting off the edge for a more rectangular crop which helped balance the image a bit more.', '2012-03-22 22:20:29.000000', NULL, 1),
