(6723974, 1005383, 66384, '<td valign="top">Very strong and dramatic.</td>', 'Very strong and dramatic.', '2012-03-27 11:29:31.000000', NULL, 1),
(6723981, 1005424, 66384, '<td valign="top">I like this a lot. Beautiful colors, great design, and interesting effect.</td>', 'I like this a lot. Beautiful colors, great design, and interesting effect.', '2012-03-27 11:33:25.000000', NULL, 1),
(6723988, 1005478, 66384, '<td valign="top">The photographer''s reflection distracts me from the portrait, which is strong and well lit.</td>', 'The photographer''s reflection distracts me from the portrait, which is strong and well lit.', '2012-03-27 11:37:00.000000', NULL, 1),
(6723998, 1005516, 66384, '<td valign="top">Nice and crisp, but a bit confusing. I think there are too many elements in this image! And the lines are disorganized, leading my eye all over the image, with no apparent resting place. I think it might be stronger with just the helmet and glasses.</td>', 'Nice and crisp, but a bit confusing. I think there are too many elements in this image! And the lines are disorganized, leading my eye all over the image, with no apparent resting place. I think it might be stronger with just the helmet and glasses.', '2012-03-27 11:49:45.000000', NULL, 1),
(6724003, 1005137, 66384, '<td valign="top">I like the tone and contrast, but over all it seems a little dark.</td>', 'I like the tone and contrast, but over all it seems a little dark.', '2012-03-27 11:54:36.000000', NULL, 1),
(6724011, 1005123, 66384, '<td valign="top">Haha, looks like she has a Pinoccio nose. I like the image.</td>', 'Haha, looks like she has a Pinoccio nose. I like the image.', '2012-03-27 12:01:02.000000', NULL, 1),
(6724013, 1005133, 66384, '<td valign="top">Lovely character portrait. I like the lighting, and the negative space imparts a lot of strength,</td>', 'Lovely character portrait. I like the lighting, and the negative space imparts a lot of strength,', '2012-03-27 12:04:17.000000', NULL, 1),
(6724021, 1005375, 116155, '<td valign="top">Great lighting.</td>', 'Great lighting.', '2012-03-27 12:21:13.000000', NULL, 1),
