(6724091, 1005279, 138630, '<td valign="top">So scholarly he looks!  Terrific focus and full frame composition.  One of my top scores (voted earlier).</td>', 'So scholarly he looks!  Terrific focus and full frame composition.  One of my top scores (voted earlier).', '2012-03-27 14:06:31.000000', NULL, 1),
(6724092, 1005336, 138630, '<td valign="top">Excellent lighting, detail and tones.  Back to comment - a very good score from me.</td>', 'Excellent lighting, detail and tones.  Back to comment - a very good score from me.', '2012-03-27 14:07:45.000000', NULL, 1),
(6724093, 1005458, 138630, '<td valign="top">I adore the look here - primitive and contemporary at the same time.  Back to comment - a very good score from me.</td>', 'I adore the look here - primitive and contemporary at the same time.  Back to comment - a very good score from me.', '2012-03-27 14:08:40.000000', NULL, 1),
(6724095, 1005495, 138630, '<td valign="top">Excellent perspective and focus  - nice and sharp on the glasses and still good throughout the frame.  I like the design elements here.  Back to comment - a very good score from me.</td>', 'Excellent perspective and focus  - nice and sharp on the glasses and still good throughout the frame.  I like the design elements here.  Back to comment - a very good score from me.', '2012-03-27 14:09:46.000000', NULL, 1),
(6724099, 1005018, 138630, '<td valign="top">I like the way you have placed the glasses over the clusters of spines, especially the lens on our right as we view.  Nice and sharp and fun -- needs a sombrero LOL  Voted earlier.</td>', 'I like the way you have placed the glasses over the clusters of spines, especially the lens on our right as we view.  Nice and sharp and fun -- needs a sombrero LOL  Voted earlier.', '2012-03-27 14:11:28.000000', NULL, 1),
(6724101, 1005383, 138630, '<td valign="top">I like the literal, concrete interpretation of a word that actually refers to a mental activity -- a nice twist that I suspect may have come from a non-native English speaker.  It''s very clever, though, and well composed so it gets a nice score from me.  Voted earlier.</td>', 'I like the literal, concrete interpretation of a word that actually refers to a mental activity -- a nice twist that I suspect may have come from a non-native English speaker.  It''s very clever, though, and well composed so it gets a nice score from me.  Voted earlier.', '2012-03-27 14:14:44.000000', NULL, 1),
(6724102, 1005318, 138630, '<td valign="top">Beautiful colors and clarity in this interesting abstract - the title suggests an updated Pac-Man but also makes me think of a transparent blue fish.  Fun and interesting.  Voted earlier.</td>', 'Beautiful colors and clarity in this interesting abstract - the title suggests an updated Pac-Man but also makes me think of a transparent blue fish.  Fun and interesting.  Voted earlier.', '2012-03-27 14:17:17.000000', NULL, 1),
